function targetTable(type:string,data:Record<string,unknown>):string{if(type==="money_entry")return"money_entries";if(type==="purchase")return"purchases";if(type==="meal")return"meals";if(type==="food")return"food_references";if(type==="recipe")return"recipes";if(type==="meal_template")return"meal_templates";if(type==="health_raw")return"health_raw_records";if(type==="asset")return"assets";if(type==="health_plan")return String(data.kind)==="habit"?"health_habit_definitions":String(data.kind)==="workout"?"workout_plans":"health_goals";return"legacy_archives";}

