async function reconcile(database:Pool|PoolClient,bundle:MigrationBundle,items:ReturnType<typeof plan>,id:string,verifiedFiles:VerifiedManifestFile[]){
  const result=await database.query<{status:string,count:string}>("select status,count(*)::text count from migration_items where batch_id=$1 group by status",[id]);const counts=Object.fromEntries(result.rows.map(row=>[row.status,Number(row.count)]));const disposed=Object.values(counts).reduce((a,b)=>a+b,0),differences:unknown[]=[],actualFacts:unknown[]=[];
  for(const item of items){const subject=bundle.owners[item.source.owner]!,verification=item.change_kind==="delete"?await verifyDeletedTarget(database,item.target.type,item.target.id,subject):await verifyTarget(database,item.target.type,item.target.id,subject,item.target.data);differences.push(...verification.differences);actualFacts.push({subject,type:item.target.type,id:item.target.id,change_kind:item.change_kind,data:verification.actual});const mapping=await database.query<{target_id:string}>("select target_id from legacy_object_maps where source_instance=$1 and source_table=$2 and source_pk_hash=$3 and source_owner=$4 and target_type=$5 and role=$6",[item.source.instance,item.source.table,item.source_pk_hash,item.source.owner,item.target.type,item.target.role]);if(mapping.rowCount!==1||mapping.rows[0]!.target_id!==item.target.id)differences.push({target_type:item.target.type,target_id:item.target.id,field:"$mapping",expected:{source:item.source,target_id:item.target.id,role:item.target.role},actual:mapping.rows});const reverse=await database.query("select source_instance,source_table,source_pk_hash,source_owner,role from legacy_object_maps where target_type=$1 and target_id=$2",[item.target.type,item.target.id]);if(reverse.rowCount!==1||reverse.rows[0]?.source_instance!==item.source.instance||reverse.rows[0]?.source_table!==item.source.table||reverse.rows[0]?.source_pk_hash!==item.source_pk_hash||reverse.rows[0]?.source_owner!==item.source.owner||reverse.rows[0]?.role!==item.target.role)differences.push({target_type:item.target.type,target_id:item.target.id,field:"$reverse_mapping",expected:{source_instance:item.source.instance,source_table:item.source.table,source_pk_hash:item.source_pk_hash,source_owner:item.source.owner,role:item.target.role},actual:reverse.rows});}
  const complete=disposed===items.length&&(counts.pending??0)===0&&(counts.blocked??0)===0&&(counts.conflict??0)===0&&differences.length===0;
  const targetFactHash=sha256({targets:actualFacts,files:verifiedFiles}),reconciledAt=new Date().toISOString();await database.query("update migration_batches set stage=$2,completed_at=case when $2='completed' then now() else null end,summary=summary||$3::jsonb where id=$1",[id,complete?"completed":"blocked",JSON.stringify({reconciled:complete,reconciled_at:reconciledAt,target_fact_hash:targetFactHash,components:items.length,differences})]);return{complete,expected_components:items.length,disposed_components:disposed,statuses:counts,source_objects:bundle.objects.length,differences,target_fact_hash:targetFactHash,reconciled_at:reconciledAt};
}
async function cutoverCheck(pool:Pool,bundle:MigrationBundle,planned:ReturnType<typeof plan>,id:string,bundleHash:string,ownerMapHash:string,verifiedFiles:VerifiedManifestFile[]){
  const client=await pool.connect(),lockKey=`shadow-life:migration:${id}`;try{await client.query("select pg_advisory_lock(hashtextextended($1,0))",[lockKey]);await client.query("begin isolation level repeatable read");try{const fresh=await reconcile(client,bundle,planned,id,verifiedFiles);const batch=await client.query<{stage:string;summary:Record<string,unknown>;bundle_hash:string;source_snapshot:string;mapper_version:string;owner_map_hash:string;mode:Mode}>("select stage,summary,bundle_hash,source_snapshot,mapper_version,owner_map_hash,mode from migration_batches where id=$1",[id]);const items=await client.query("select count(*) filter(where status in ('pending','blocked','conflict'))::int unresolved from migration_items where batch_id=$1",[id]);const projections=await client.query("select count(*) filter(where state<>'completed')::int incomplete from projection_checkpoints",[]);const healthWork=await client.query("select count(*) filter(where state<>'completed')::int incomplete from health_normalization_queue",[]);const healthDays=await client.query("select count(*) filter(where not valid)::int incomplete from health_projection_invalidations",[]);const epochs=await client.query<{domain:string;epoch:number;stage:string;target_schema:string}>("select domain,epoch,stage,target_schema from write_epochs order by domain",[]),row=batch.rows[0];const checks={final_delta_batch:row?.mode==="final_delta",source_snapshot_bound:row?.bundle_hash===bundleHash&&row.source_snapshot===bundle.source_snapshot&&row.mapper_version===bundle.mapper_version&&row.owner_map_hash===ownerMapHash,batch_completed:row?.stage==="completed",target_reconciled:fresh.complete&&row?.summary?.reconciled===true,migration_items_resolved:items.rows[0]?.unresolved===0,projections_completed:projections.rows[0]?.incomplete===0,health_normalization_completed:healthWork.rows[0]?.incomplete===0,health_daily_projections_completed:healthDays.rows[0]?.incomplete===0,write_epochs_frozen:epochs.rows.length===2&&epochs.rows.every(epoch=>epoch.stage==="read_only"),write_epochs:epochs.rows};const ready=checks.final_delta_batch&&checks.source_snapshot_bound&&checks.batch_completed&&checks.target_reconciled&&checks.migration_items_resolved&&checks.projections_completed&&checks.health_normalization_completed&&checks.health_daily_projections_completed&&checks.write_epochs_frozen;await client.query("commit");return{ready,checks,source_snapshot:bundle.source_snapshot,target_fact_hash:fresh.target_fact_hash,reconciled_at:fresh.reconciled_at};}catch(error){await client.query("rollback");throw error;}}finally{await client.query("select pg_advisory_unlock(hashtextextended($1,0))",[lockKey]).catch(()=>undefined);client.release();}
}

async function verifyTarget(pool:Pool|PoolClient,type:string,id:string,subject:string,expected:Record<string,unknown>):Promise<{differences:unknown[];actual:unknown}>{
  let actual:Record<string,unknown>|undefined;
  if(type==="money_entry")actual=(await pool.query("select record.id record_id,entry.entry_type,entry.amount::text amount,entry.currency,entry.occurred_on::text,entry.occurred_at::text,entry.time_zone,entry.note,entry.category,entry.counterparty,entry.payment_method,entry.source_scale,entry.revision,record.state,record.revision record_revision,record.confirmed_at::text,record.voided_at::text from money_entries entry join consumption_records record on record.id=entry.record_id where entry.id=$1 and entry.subject_id=$2",[id,subject])).rows[0];
  else if(type==="purchase"){actual=(await pool.query("select purchase.record_id,purchase.merchant,purchase.amount::text amount,purchase.currency,purchase.category,purchase.occurred_on::text,purchase.occurred_at::text,purchase.time_zone,purchase.note,purchase.scene,purchase.channel_name_raw,purchase.place_ref,purchase.rating,purchase.would_repeat,purchase.revision,record.state,record.confirmed_at::text,record.voided_at::text from purchases purchase join consumption_records record on record.id=purchase.record_id where purchase.id=$1 and purchase.subject_id=$2",[id,subject])).rows[0];if(actual){actual.items=(await pool.query("select id,position,raw_name,quantity::text,unit_price::text,unit,line_amount::text,category_key from purchase_items where purchase_id=$1 order by position",[id])).rows;const money=(await pool.query("select id,entry_type,amount::text amount,currency,note,category,counterparty,payment_method,source_scale,revision from money_entries where record_id=$1",[actual.record_id])).rows[0];actual.money_entry=money??null;}}
  else if(type==="meal"){actual=(await pool.query("select meal.occurred_on::text,meal.occurred_at::text,meal.time_zone,meal.meal_type,meal.note,meal.state,meal.revision,(select grouping_origin from intake_items where meal_id=meal.id and effective order by position limit 1) grouping_origin from meals meal where meal.id=$1 and meal.subject_id=$2",[id,subject])).rows[0];if(actual){const rows=(await pool.query("select id,name,food_ref_id,quantity::text,unit,energy_kcal::text,estimate,evidence_note,free_text,amount_g::text,protein_g::text,fat_g::text,carb_g::text,fiber_g::text,sodium_mg::text,consumed_fraction::text,provenance,grouping_origin,revision from intake_items where meal_id=$1 and effective order by position",[id])).rows;actual.items=rows;}}
  else if(type==="food")actual=(await pool.query("select name,serving_amount::text,serving_unit,nutrients,provenance,state,revision from food_references where id=$1 and subject_id=$2",[id,subject])).rows[0];
  else if(type==="recipe"){actual=(await pool.query("select title,servings::text,instructions,state,revision from recipes where id=$1 and subject_id=$2",[id,subject])).rows[0];if(actual)actual.items=(await pool.query("select snapshot from recipe_items where recipe_id=$1 order by position",[id])).rows.map(row=>row.snapshot);}
  else if(type==="meal_template"){actual=(await pool.query("select name,revision from meal_templates where id=$1 and subject_id=$2",[id,subject])).rows[0];if(actual)actual.items=(await pool.query("select snapshot from meal_template_items where template_id=$1 order by position",[id])).rows.map(row=>row.snapshot);}
  else if(type==="health_plan"){const kind=String(expected.kind),table=targetTable(type,expected),name=kind==="workout"?"title":"name";actual=(await pool.query(`select ${name} name,${kind==="goal"?"metric_key,target_value::text target_value,unit,due_on::text due_on,":""}${kind==="workout"?"schedule,detail,":""}${kind==="habit"?"schedule,":""}state,revision from ${table} where id=$1 and subject_id=$2`,[id,subject])).rows[0];if(actual)actual.kind=kind;}
  else if(type==="health_raw")actual=(await pool.query("select source.source_type,source.instance_key source_instance_key,source.fingerprint source_fingerprint,raw.record_type,raw.client_record_id,raw.current_version::text record_version,raw.current_sync_epoch sync_epoch,raw.parse_version,revision.payload,revision.change_kind from health_raw_records raw join health_source_instances source on source.id=raw.source_instance_id join health_raw_revisions revision on revision.raw_id=raw.id and revision.record_version=raw.current_version where raw.id=$1 and raw.subject_id=$2",[id,subject])).rows[0];
  else if(type==="asset")actual=(await pool.query("select asset.media_type,replace(encode(blob.bytes,'base64'),E'\\n','') bytes_base64,octet_length(blob.bytes)::int byte_size,version.sha256,reference.target_id meal_id,source.external_id filename from assets asset join asset_versions version on version.asset_id=asset.id join asset_blobs blob on blob.asset_version_id=version.id join asset_references reference on reference.asset_id=asset.id and reference.subject_id=asset.subject_id and reference.target_type='meal' join sources source on source.asset_version_id=version.id and source.subject_id=asset.subject_id where asset.id=$1 and asset.subject_id=$2",[id,subject])).rows[0];
  else actual=(await pool.query("select archive.source_instance,archive.source_table,archive.source_snapshot,archive.chunk_no,archive.chunk_count,archive.row_count,archive.content,archive.content_hash,archive.state,archive.revision,item.title,revision.tags from legacy_archives archive join library_items item on item.id=archive.id and item.subject_id=archive.subject_id join library_revisions revision on revision.item_id=item.id and revision.revision=item.current_revision where archive.id=$1 and archive.subject_id=$2",[id,subject])).rows[0];
  if(!actual)return{differences:[{target_type:type,target_id:id,field:"$",expected:"present",actual:"missing"}],actual:null};const differences:unknown[]=[];for(const [key,value] of Object.entries(expected)){if(key==="confirmed_at"||key==="voided_at"||key==="time_zone"&&actual[key]===undefined)continue;const left=normalize(value),right=normalize(project(actual[key],value));if(canonical(left)!==canonical(right))differences.push({target_type:type,target_id:id,field:key,expected:left,actual:right});}return{differences,actual:normalize(actual)};
}
async function verifyDeletedTarget(pool:Pool|PoolClient,type:string,id:string,subject:string):Promise<{differences:unknown[];actual:unknown}>{const result=await verifyTarget(pool,type,id,subject,{}),expectedState=type==="money_entry"||type==="purchase"?"voided":"deleted";let actual=result.actual&&typeof result.actual==="object"?(result.actual as Record<string,unknown>).state:undefined;if(type==="health_raw")actual=(await pool.query("select state from health_raw_records where id=$1 and subject_id=$2",[id,subject])).rows[0]?.state;if(actual!==expectedState)result.differences.push({target_type:type,target_id:id,field:"state",expected:expectedState,actual});return result;}
function normalize(value:unknown):unknown{if(typeof value==="string"&&/^\d{4}-\d{2}-\d{2}[T ].*(?:Z|[+-]\d{2}(?::?\d{2})?)$/u.test(value)){const parsed=Date.parse(value);if(Number.isFinite(parsed))return new Date(parsed).toISOString();}if(typeof value==="string"&&/^-?\d+(?:\.\d+)?$/u.test(value)){const normalized=value.replace(/(\.\d*?)0+$/u,"$1").replace(/\.$/u,"");return normalized==="-0"?"0":normalized;}if(Array.isArray(value))return value.map(normalize);if(value&&typeof value==="object")return Object.fromEntries(Object.entries(value as Record<string,unknown>).filter(([,item])=>item!==null&&item!==undefined).map(([key,item])=>[key,normalize(item)]));return value;}
function project(actual:unknown,expected:unknown):unknown{if(typeof expected==="number"&&typeof actual==="string"&&/^-?\d+(?:\.\d+)?$/u.test(actual))return Number(actual);if(Array.isArray(expected)){if(!Array.isArray(actual))return actual;if(expected.length===0)return actual.length===0?[]:actual.map(()=>"unexpected");return actual.map((item,index)=>project(item,expected[index]??expected[0]));}if(expected&&typeof expected==="object"&&actual&&typeof actual==="object"){const source=actual as Record<string,unknown>;return Object.fromEntries(Object.keys(expected as Record<string,unknown>).map(key=>[key,project(source[key],(expected as Record<string,unknown>)[key])]));}return actual;}
